qss:
QWidget { background: #0055aa; color: #ffffff; font-family: "Topaz", "Courier New", monospace; font-size: 10pt; }
QMainWindow, QDialog { background: #0055aa; }
QLabel { background: transparent; }
QFrame#Sidebar, QFrame#HeaderBar, QFrame#ComposerFrame, QFrame#ChatSurface { background: #0077aa; border: 1px solid #55aaff; border-radius: 16px; }
QLabel#TitleLabel { font-size: 16pt; font-weight: 700; color: #ffffff; }
QLabel#SubtleLabel { color: #aaddff; }
QPushButton { background: #006699; color: #ffffff; border: 1px solid #55aaff; border-radius: 12px; padding: 8px 12px; }
QPushButton:hover { background: #0088bb; }
QPushButton#AccentButton { background: #ff8800; border: 1px solid #ffaa33; color: #ffffff; font-weight: 700; }
QPushButton#AccentButton:hover { background: #ffaa33; }
QPushButton#DangerButton { background: #aa2244; }
QComboBox, QLineEdit, QPlainTextEdit, QTextEdit, QListWidget, QTextBrowser, QSpinBox { background: #001f55; color: #ffffff; border: 1px solid #55aaff; border-radius: 12px; padding: 8px; }
QListWidget::item { border-radius: 10px; padding: 8px; margin: 2px; }
QListWidget::item:selected { background: #003f7f; border: 1px solid #ff8800; }
QScrollArea { border: none; background: transparent; }
QScrollBar:vertical { background: #0077aa; width: 16px; margin: 2px; border-radius: 6px; }
QScrollBar::handle:vertical { background: #55aaff; min-height: 32px; border-radius: 7px; }
QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical { height: 0px; }
QScrollBar::add-page:vertical, QScrollBar::sub-page:vertical { background: transparent; }
QProgressBar { border: 1px solid #55aaff; border-radius: 10px; background: #001f55; text-align: center; min-height: 18px; }
QProgressBar::chunk { background: #ff8800; border-radius: 8px; }
QFrame#AssistantBubbleCard { background: #0077aa; border: 1px solid #55aaff; border-left: 4px solid #ff8800; border-radius: 16px; }
QFrame#UserBubbleCard { background: #003f7f; border: 1px solid #55aaff; border-radius: 16px; }
